public async Task HandleAsync(OrderPlaced message, CancellationToken ct)
{
    if (await db.ProcessedMessages.AnyAsync(x => x.Id == message.Id, ct))
        return;

    inventory.Reserve(message.OrderId, message.Lines);
    db.ProcessedMessages.Add(new ProcessedMessage(message.Id, clock.UtcNow));

    await db.SaveChangesAsync(ct);
}

public sealed record OrderPlaced(Guid Id, Guid OrderId,
    IReadOnlyList<OrderLine> Lines);

public sealed class PlaceOrderHandler(
    IOrderRepository orders,
    IUnitOfWork unitOfWork,
    IClock clock)
{
    public async Task<Guid> HandleAsync(PlaceOrder command, CancellationToken ct)
    {
        var order = Order.Place(command.CustomerId, command.Lines, clock.UtcNow);
        await orders.AddAsync(order, ct);
        await unitOfWork.SaveChangesAsync(ct);
        return order.Id;
    }
}

public interface IPricingStrategy
{
    decimal Calculate(Order order);
}

public sealed class LoyaltyPricing : IPricingStrategy
{
    public decimal Calculate(Order order) =>
        order.Subtotal >= 100m
            ? order.Subtotal * 0.90m
            : order.Subtotal;
}

public sealed class Checkout(IPricingStrategy pricing)
{
    public decimal Total(Order order) => pricing.Calculate(order);
}

public sealed class OrderTests
{
    [Fact]
    public void AddLine_WhenQuantityIsZero_RejectsChange()
    {
        var order = Order.Create(CustomerId.New());

        var action = () => order.AddLine(ProductId.New(), quantity: 0);

        action.Should().Throw<DomainException>()
            .WithMessage("Quantity must be positive.");
        order.Lines.Should().BeEmpty();
    }
}

public async Task<ProductDto?> FindAsync(Guid id, CancellationToken ct)
{
    var key = $"product:{id}";
    if (cache.TryGetValue(key, out ProductDto? cached))
        return cached;

    var product = await database.Products
        .AsNoTracking()
        .Where(x => x.Id == id)
        .Select(x => new ProductDto(x.Id, x.Name, x.Price))
        .SingleOrDefaultAsync(ct);

    if (product is not null)
        cache.Set(key, product, TimeSpan.FromMinutes(2));
    return product;
}

